void analyze_null_deref(ExprNode* expr, DataflowState& state) {
  if (expr->kind == DEREF) {
    NullState ns = state.get_null_state(expr->operand);
    if (ns == POSSIBLY_NULL || ns == DEFINITELY_NULL) {
      report_defect(expr, NULL_DEREF);
    }
  }
}

class DataflowLattice {
public:
  NullState meet(NullState a, NullState b) {
    if (a == b) return a;
    if (a == UNKNOWN) return b;
    if (b == UNKNOWN) return a;
    return POSSIBLY_NULL;
  }
};

